_DEP_ORDER = ['parse_dxf', 'analyze', 'engine', 'beambar_engine', 'hatch_engine', 'compute_column_text', 'compute_beamtext_slabmarker', 'compute_beambar3', 'compute_slabbar3', 'perimeter', 'patch_style', 'patch_slab_marker', 'patcher']

def _load_deps():
    pending = [m for m in _DEP_ORDER if m not in sys.modules]
    while pending:
        progressed = False
        errors = {}
        for _m in list(pending):
            mod = types.ModuleType(_m)
            mod.__file__ = _m + ".py"
            sys.modules[_m] = mod
            try:
                exec(compile(_DEPS_SRC[_m], _m + ".py", "exec"), mod.__dict__)
            except (ImportError, AttributeError) as e:
                del sys.modules[_m]
                errors[_m] = e
                continue
            pending.remove(_m)
            progressed = True
        if not progressed:
            raise ImportError("Αδιέξοδο εξαρτήσεων: %r" % errors)

_load_deps()
# Εκτέλεση του πραγματικού pipeline_v11 ΜΕΣΑ σε αυτό το module
exec(compile(_MAIN_SRC, "pipeline_v11.py", "exec"), globals())

def _run_script(name, argv):
    old = sys.argv
    sys.argv = [name] + list(argv)
    try:
        g = {"__name__": "__main__", "__file__": name + ".py"}
        exec(compile(_DEPS_SRC["@" + name], name + ".py", "exec"), g)
    finally:
        sys.argv = old

def tidy(src, dst, pkl="offsets.pkl"):
    _run_script("run_any", [src, dst, pkl])

def audit(out_dxf, in_dxf):
    _run_script("audit_output", [out_dxf, in_dxf])

def verify(in_dxf, pkl):
    _run_script("verify_all", [in_dxf, pkl])

if __name__ == "__main__":
    _c = sys.argv[1] if len(sys.argv) > 1 else ""
    if _c == "tidy":
        tidy(*sys.argv[2:])
    elif _c == "audit":
        audit(*sys.argv[2:])
    elif _c == "verify":
        verify(*sys.argv[2:])
    else:
        print(__doc__)
